[CmdletBinding()]param([string]$RepoRoot='.',[string]$OutputRoot='',[switch]$Force)
$ErrorActionPreference='Stop';$Root=(Resolve-Path -LiteralPath $RepoRoot).Path;$V=Get-Content (Join-Path $Root 'VERSION.json') -Raw|ConvertFrom-Json;if([string]$V.ecosystem_version-ne'1.2.8'){throw 'Unified version mismatch.'};if([string]::IsNullOrWhiteSpace($OutputRoot)){$OutputRoot=Join-Path $Root '.artifacts\release-kit\1.2.8\companion'};if(Test-Path $OutputRoot){if(-not$Force){throw "Output exists: $OutputRoot"};Remove-Item $OutputRoot -Recurse -Force};New-Item -ItemType Directory -Force $OutputRoot|Out-Null;$Stage=Join-Path ([IO.Path]::GetTempPath()) ('companion-1.2.8-'+[guid]::NewGuid().ToString('N'));$PackRoot=Join-Path $Stage 'agentic-companion-1.2.8';$Knowledge=Join-Path $PackRoot 'knowledge';New-Item -ItemType Directory -Force $Knowledge|Out-Null
$Files=@('00_AGENTIC_PIPELINE_INDEX_v1.2.8.md','01_CONTEXT_SPLIT_POLICY.md','02_AGENT_TASK_PACK_CONTRACT_v1.2.8.md','03_PRODUCT_EVIDENCE_CONTROL_PLANE.md','04_PROJECT_AUDIT_AND_RECOVERY.md','05_DOMAIN_SPECIFIC_LESSONS_OPTIONAL.md','06_RUNTIME_TRUTH_REVIEW_POLICY.md','07_RUNTIME_HANDSHAKE_AND_COMMAND_ROUTING.md','08_PHASE_CONTRACT_AND_PROGRESS_POLICY.md','09_EVIDENCE_LEVELS_AND_BLOCKER_POLICY.md','10_STATUS_AND_FINDING_LIFECYCLE.md','11_PROMPT_COMPILER_AND_RESULT_AUTHORITY.md','12_GOLDEN_EVALS.md','13_LOCAL_CONTROL_TOOLS.md','14_AUTONOMOUS_CONVERGENCE_AND_AUDIT_COVERAGE.md','15_OWNER_OUTPUT_PRESENTATION.md')
try{Copy-Item (Join-Path $Root 'docs\companion\01_PROJECT_INSTRUCTIONS_v1.2.8.md') (Join-Path $PackRoot '01_PROJECT_INSTRUCTIONS_v1.2.8.md');foreach($Name in $Files){$Source=Join-Path $Root ('docs\companion\'+$Name);if(!(Test-Path $Source)){throw "Companion source missing: $Name"};Copy-Item $Source (Join-Path $Knowledge $Name)};Copy-Item (Join-Path $Root 'docs\companion\SYSTEM_PROMPT_GPT56_COMPANION_v1.2.8.md') $PackRoot;Copy-Item (Join-Path $Root 'docs\companion\README_INSTALL_RU_v1.2.8.md') $PackRoot;Copy-Item (Join-Path $Root 'docs\companion\VERSION.json') $PackRoot;$MF=Get-ChildItem $PackRoot -Recurse -File|Sort-Object FullName|%{[ordered]@{path=[IO.Path]::GetRelativePath($PackRoot,$_.FullName).Replace('\','/');size_bytes=$_.Length;sha256=(Get-FileHash $_.FullName -Algorithm SHA256).Hash.ToLowerInvariant()}};$M=[ordered]@{schema_version='1.0.0';ecosystem_version='1.2.8';companion_version='1.2.8';knowledge_module_count=16;action_packet_extension='.json';files=@($MF)};[IO.File]::WriteAllText((Join-Path $PackRoot 'MANIFEST.json'),($M|ConvertTo-Json -Depth 10),[Text.UTF8Encoding]::new($false));$Zip=Join-Path $OutputRoot 'agentic-companion-1.2.8.zip';Compress-Archive -Path (Join-Path $PackRoot '*') -DestinationPath $Zip -CompressionLevel Optimal -Force;Write-Host "Companion pack built: $Zip"}finally{Remove-Item $Stage -Recurse -Force -ErrorAction SilentlyContinue}
